import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"節","description":"周易集解 - 節","frontmatter":{"title":"節","description":"周易集解 - 節"},"headers":[],"relativePath":"classics/jijie/060.md","filePath":"classics/jijie/060.md"}'),l={name:"classics/jijie/060.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="節" tabindex="-1">節 <a class="header-anchor" href="#節" aria-label="Permalink to “節”">​</a></h1><h2 id="節-1" tabindex="-1">節 <a class="header-anchor" href="#節-1" aria-label="Permalink to “節”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>節，亨，苦節不可貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物不可以終離，故受之以節。</p><p>崔憬曰：離散之道，不可終行，當宜節止之。故言物不可以終離，受之以節。</p><p>虞翻曰：泰三之五，天地交也。五當位以節，中正以通，故節亨也。</p><p>虞翻曰：謂上也，應在三。三變成離，火炎上作，苦位在火上，故苦節。雖得位，乘陽，故不可貞也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：節亨，剛柔分而剛得中，苦節不可貞，其道窮也。說以行險，當位以節，中正以通，天地節而四時成。節以制度，不傷財，不害民。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>盧氏曰：此本泰卦。分乾九三升坤五，分坤六五下處乾三，是剛柔分而剛得中也。</p><p>虞翻曰：位極於上，乘陽，故窮也。</p><p>虞翻曰：兌說，坎險，震為行，故說以行險也。</p><p>虞翻曰：中正謂五。坎為通也。</p><p>虞翻曰：泰乾天，坤地；震春，兌秋，坎冬。三動，離為夏。故天地節而四時成也。</p><p>虞翻曰：艮手稱制。坤數十，為度。坤又為害，為民，為財。二動體剝，剝為傷。三出複位，成既濟定，坤剝不見。故｢節以制度，不傷財，不害民｣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤上有水，節。君子以制數度，議德行。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：澤上有水，以堤防為節。</p><p>虞翻曰：君子，泰乾也。艮止為制，坤為度，震為議，為行，乾為德，故｢以制數度，議德行｣。乾三之五，為制數度。坤五之乾，為議德行也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，不出戶庭，無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：泰坤為戶，艮為庭，震為出；初得位應四，故｢不出戶庭，無咎｣矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不出戶庭，知通塞也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：坎為通，二變坤土，壅初為塞。</p><p>崔憬曰：為節之始，有應於四。四為坎險，不通之象。以節崇塞，雖不通，可謂知通塞矣。戶庭，室庭也。慎密守節，故不出焉，而無咎也。</p><p>案：初九應四。四互坎艮。艮為門闕。四居艮中，是為內戶，戶庭之象也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，不出門庭，兇。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：變而之坤，艮為門庭。二失位不變，出門應五，則兇。故言不出門庭兇矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不出門庭兇，失時極也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：極，中也。未變之正，失時極矣。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，不節若，則嗟若，無咎。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：三，節家君子也。失位，故節若。嗟，哀號聲。震為音聲，為出。三動得正，而體離坎，涕流出目，故則嗟若。得位乘二，故無咎也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不節之嗟，又誰咎也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：若，辭也。以陰處陽，以柔乘剛，違節之道，以至哀嗟。自己所致，無所怨咎，故曰又誰咎矣。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，安節，亨。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：二已變，艮止坤安。得正承五，有應於初，故安節亨。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：安節之亨，承上道也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：言四得正奉五，上通於君，故曰承上道也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，甘節，吉。往有尚。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：得正居中，坎為美，故甘節吉。往謂二。二失正，變往應五，故往有尚也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：甘節之吉，居位中也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：艮為居，五為中，故居位中也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，苦節，貞兇，悔亡。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：二三變，有兩離，火炎上作苦，故苦節。乘陽，故貞兇。得位，故悔亡。</p><p>乾寶曰：《彖》稱苦節不可貞，在此爻也。稟險伏之教，懷貪狼之志，以苦節之性，而遇甘節之主，必受其誅，華士、少正卯之爻也。故曰貞兇。苦節既兇，甘節志得，故曰悔亡。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：苦節貞兇，其道窮也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：乘陽於上，無應於下，故其道窮也。</p>',74)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
